{"packet_id":"D042-01","doc_id":"D042","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"RSO annual allowable rent increase, July 2025 through June 2026","requirement":"A landlord of a rental unit subject to the City of Los Angeles Rent Stabilization Ordinance may raise rent by no more than 3% for the period July 1, 2025 through June 30, 2026, with at least 30 days' written notice for increases under 10%.","key_value":"3% (July 1, 2025 – June 30, 2026)","coverage_conditions":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance (RSO).","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance"},"exemptions":null,"penalty":null,"effective_date":"2025-07-01","citation":"Los Angeles Rent Stabilization Ordinance","quoted_span":"Annual rent increases for rental units subject to the City of Los Angeles Rent Stabilization Ordinance (RSO), effective July 1, 2025, through June 30, 2026 is 3%.","interaction":"State law requires landlords to provide 30 days' written advance notice of rent increases of less than 10%.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D042-01","doc_id":"D042","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"RSO bar on utility percentage increases from February 2, 2026","requirement":"Starting February 2, 2026, a landlord of an RSO unit may no longer include any additional percentage increase for utilities in a rent increase.","key_value":"No additional utility percentage increase","coverage_conditions":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance (RSO).","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance"},"exemptions":null,"penalty":null,"effective_date":"2026-02-02","citation":"Los Angeles Rent Stabilization Ordinance","quoted_span":"Beginning February 2, 2026, a landlord can no longer include any additional percentage increase for utilities.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D042-01","doc_id":"D042","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"RSO fee pass-through surcharge","requirement":"A landlord may collect the RSO fee from tenants at a rate of $1.61 per month for 12 months each year, but only after registering the units and giving the tenant written notice.","key_value":"$1.61/month for 12 months ($38.75 per unit)","coverage_conditions":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance (RSO).","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance"},"exemptions":null,"penalty":null,"effective_date":"2020-01-01","citation":"Los Angeles Rent Stabilization Ordinance","quoted_span":"RSO Pass Through Amount: Effective January 1, 2020, the RSO fee is a total of $38.75 per unit which landlords may collect from tenants at a rate of $1.61 per month for 12 months each year with a proper written notice.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D042-01","doc_id":"D042","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"SCEP fee pass-through surcharge","requirement":"A landlord may collect the SCEP fee from tenants at a rate of $2.83 per month for 12 months each year, but only after registering the units and giving the tenant written notice.","key_value":"$2.83/month for 12 months ($67.94 per unit)","coverage_conditions":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance (RSO).","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Rental units subject to the City of Los Angeles Rent Stabilization Ordinance"},"exemptions":null,"penalty":null,"effective_date":"2022-01-01","citation":"Los Angeles Rent Stabilization Ordinance","quoted_span":"SCEP Pass Through Amount: Effective January 1, 2022, the SCEP fee is a total of $67.94 per unit which landlords may collect from tenants at a rate of $2.83 per month for 12 months each year with a proper written notice.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
